import{_ as o,a0 as d,w as p,s as r,ao as n,I as i,x as s,a1 as a,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何解決 Linux 中“磁盤空間不足”的問題 | LCTT x X-CMD","titleTemplate":false,"description":"如何解決 Linux 中“磁盤空間不足”的問題 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何解決 Linux 中“磁盤空間不足”的問題 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何解決 Linux 中“磁盤空間不足”的問題 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171115 How to Fix the ‘No Space Left on Device- Error on Linux","title":"如何解決 Linux 中“磁盤空間不足”的問題","tag":"201801","desc":""},"relativePath":"201801/20171115 How to Fix the ‘No Space Left on Device- Error on Linux.md","filePath":"[post].md"}'),u={name:"201801/20171115 How to Fix the ‘No Space Left on Device- Error on Linux.md"};function h(k,e,c,g,f,m){const t=d("Link");return p(),r("div",null,[e[19]||(e[19]=n('<h1 id="如何解決-linux-中-磁盤空間不足-的問題" tabindex="-1">如何解決 Linux 中“磁盤空間不足”的問題 <a class="header-anchor" href="#如何解決-linux-中-磁盤空間不足-的問題" aria-label="Permalink to “如何解決 Linux 中“磁盤空間不足”的問題”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2017/10/no-space-feat.jpg" alt=""></p><p>明明有很多剩餘空間，但 Linux 系統依然提示沒有空間剩餘。為什麼會這樣呢？Linux 偶爾會有一些令人沮喪的模糊的錯誤消息出現，而這就是其中一種。不過這種錯誤通常都是由某幾種因素導致的。</p><h3 id="通過-du-和-df-檢查磁盤空間" tabindex="-1">通過 du 和 df 檢查磁盤空間 <a class="header-anchor" href="#通過-du-和-df-檢查磁盤空間" aria-label="Permalink to “通過 du 和 df 檢查磁盤空間”">​</a></h3><p>在開始行動前，最好先檢查一下是否磁盤上是否確實還有空間剩餘。雖然桌面環境的工具也很不錯，但命令列上的工具更直接，要好的多。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/10/no-space-du.jpg" alt="Linux Filesystem du" title="Linux Filesystem du"></p><p>首先讓我們看看 <code>du</code> 命令。用它來檢查問題磁盤所在的掛載點目錄。本文假設出問題的分區掛載點為根目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo du -sh /</span></span></code></pre></div><p><img src="https://www.maketecheasier.com/assets/uploads/2017/10/no-space-df.jpg" alt="Linux Filesystem df" title="Linux Filesystem df"></p><p>由於它要遍歷磁盤中的所有文件，因此需要花費一點時間。現在再讓我們試試 <code>df</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo df -h</span></span></code></pre></div><p>把根目錄和在其中掛載的文件系統加在這條命令的後面。比如，若你的有一個獨立的磁盤掛載到 <code>/home</code>，那麼除了根目錄之外，你也需要把它加進來。使用空間的總和應該跟你 <code>du</code> 命令得到的結果接近。否則的話，就説明可能有已刪除文件的文件被進程佔用。</p><p>當然，這裏主要專注點在於這些命令的結果是否要小於磁盤的大小。如果確實小於磁盤大小，那麼很明顯有很多地方不對勁。</p>',13)),i("p",null,[e[1]||(e[1]=i("strong",null,"相關",-1)),e[2]||(e[2]=s("：",-1)),a(t,{href:"https://www.maketecheasier.com/agedu-analyze-hard-disk-space-usage-in-linux/",title:"Use Agedu to Analyze Hard Disk Space Usage in Linux"},{default:l(()=>[...e[0]||(e[0]=[s("使用 Agedu 分析硬盤空間使用狀況 ",-1)])]),_:1})]),e[20]||(e[20]=n('<h3 id="可能的原因" tabindex="-1">可能的原因 <a class="header-anchor" href="#可能的原因" aria-label="Permalink to “可能的原因”">​</a></h3><p>這裏列出了一些產生這種情況的主要原因。若你發現 <code>du</code> 和 <code>df</code> 的結果之間有差別，那麼可以直接檢查第一項原因。否則從第二項原因開始檢查。</p><h4 id="已刪除文件被進程所佔用" tabindex="-1">已刪除文件被進程所佔用 <a class="header-anchor" href="#已刪除文件被進程所佔用" aria-label="Permalink to “已刪除文件被進程所佔用”">​</a></h4><p>有時，文件可能已經被刪掉了，但有進程依然在使用它。在進程運行期間，Linux 不會釋放該文件的存儲空間。你需要找出這個進程然後重啓這個進程。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2017/10/no-space-process.jpg" alt="Check processes for deleted files" title="Check processes for deleted files"></p><p>使用下面命令來定位進程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo lsof / | grep deleted</span></span></code></pre></div><p>這應該會列出出問題的進程了，然後重啓該進程。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl restart service_name</span></span></code></pre></div><h4 id="i-節點不夠了" tabindex="-1">i 節點不夠了 <a class="header-anchor" href="#i-節點不夠了" aria-label="Permalink to “i 節點不夠了”">​</a></h4><p><img src="https://www.maketecheasier.com/assets/uploads/2017/10/no-space-inode.jpg" alt="Linux check filesystem inodes" title="Linux check filesystem inodes"></p><p>文件系統中有一些稱為 “<ruby>i 節點<rt>inode</rt></ruby>” 的元數據，其用來保存文件的相關信息。很多文件系統中的 i 節點數量是固定的，因此很可能 i 節點已經耗盡了而文件系統本身還沒有用完。你可以使用 <code>df</code> 來檢查。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo df -i /</span></span></code></pre></div><p>比較一下已用的 i 節點和總共的 i 節點數量。如果沒有可用的 i 節點了，那麼很不幸，你也無法擴充 i 節點。刪除一些無用的和過期的文件來釋放一些 i 節點吧。</p><h4 id="環塊" tabindex="-1">環塊 <a class="header-anchor" href="#環塊" aria-label="Permalink to “環塊”">​</a></h4><p>最後一個很常見的問題就是壞的文件系統塊。除非另有標記，否則操作系統很可能會認為這些塊都是可用的，這會導致文件系統損壞或者硬盤壞死。最好是使用帶 <code>-cc</code> 標誌的 <code>fsck</code> 搜索並標記出這些塊。記住，你不能使用正在使用的文件系統（LCTT 譯註：即包含壞塊的文件系統）中的 <code>fsck</code> 命令。你應該會要用到 live CD。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo fsck -vcck /dev/sda2</span></span></code></pre></div><p>很明顯，這裏需要使用你想檢查的磁盤路徑取代命令中的磁盤位置。另外，要注意，這恐怕會花上很長一段時間。</p>',18)),i("p",null,[e[4]||(e[4]=i("strong",null,"相關",-1)),e[5]||(e[5]=s("：",-1)),a(t,{href:"https://www.maketecheasier.com/check-repair-filesystem-fsck-linux/",title:"Check and Repair Your Filesystem With fsck [Linux]"},{default:l(()=>[...e[3]||(e[3]=[s("使用 fsck 檢查並修復你的文件系統 [Linux]",-1)])]),_:1})]),e[21]||(e[21]=i("p",null,"希望這些方案能解決你的問題。這種問題在任何情況下都不是那麼容易診斷的。但是，在運氣好的情況下，你可以把文件系統清理乾淨並讓你的硬盤再次正常工作。",-1)),e[22]||(e[22]=i("hr",null,null,-1)),i("p",null,[e[7]||(e[7]=s("via: ",-1)),a(t,{href:"https://www.maketecheasier.com/fix-linux-no-space-left-on-device-error/"},{default:l(()=>[...e[6]||(e[6]=[s("https://www.maketecheasier.com/fix-linux-no-space-left-on-device-error/",-1)])]),_:1})]),i("p",null,[e[11]||(e[11]=s("作者：",-1)),a(t,{href:"https://www.maketecheasier.com/author/nickcongleton/"},{default:l(()=>[...e[8]||(e[8]=[s("Nick Congleton",-1)])]),_:1}),e[12]||(e[12]=s(" 譯者：",-1)),a(t,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[9]||(e[9]=[s("lujun9972",-1)])]),_:1}),e[13]||(e[13]=s(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:l(()=>[...e[10]||(e[10]=[s("wxy",-1)])]),_:1})]),i("p",null,[e[16]||(e[16]=s("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[14]||(e[14]=[s("LCTT",-1)])]),_:1}),e[17]||(e[17]=s(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:l(()=>[...e[15]||(e[15]=[s("Linux中國",-1)])]),_:1}),e[18]||(e[18]=s(" 榮譽推出",-1))])])}const L=o(u,[["render",h]]);export{w as __pageData,L as default};
